package com.abysshighlighter;

import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.ObjectID;

enum AbyssRiftRune
{
	AIR(ObjectID.ABYSS_EXIT_TO_AIR, ItemID.AIRRUNE, "Air"),
	BLOOD(ObjectID.ABYSS_EXIT_TO_BLOOD_PARENT, ItemID.BLOODRUNE, "Blood"),
	BODY(ObjectID.ABYSS_EXIT_TO_BODY, ItemID.BODYRUNE, "Body"),
	CHAOS(ObjectID.ABYSS_EXIT_TO_CHAOS, ItemID.CHAOSRUNE, "Chaos"),
	COSMIC(ObjectID.ABYSS_EXIT_TO_COSMIC, ItemID.COSMICRUNE, "Cosmic"),
	DEATH(ObjectID.ABYSS_EXIT_TO_DEATH, ItemID.DEATHRUNE, "Death"),
	EARTH(ObjectID.ABYSS_EXIT_TO_EARTH, ItemID.EARTHRUNE, "Earth"),
	FIRE(ObjectID.ABYSS_EXIT_TO_FIRE, ItemID.FIRERUNE, "Fire"),
	LAW(ObjectID.ABYSS_EXIT_TO_LAW, ItemID.LAWRUNE, "Law"),
	MIND(ObjectID.ABYSS_EXIT_TO_MIND, ItemID.MINDRUNE, "Mind"),
	NATURE(ObjectID.ABYSS_EXIT_TO_NATURE, ItemID.NATURERUNE, "Nature"),
	SOUL(ObjectID.ABYSS_EXIT_TO_SOUL, ItemID.SOULRUNE, "Soul"),
	WATER(ObjectID.ABYSS_EXIT_TO_WATER, ItemID.WATERRUNE, "Water");

	private static final Map<Integer, AbyssRiftRune> BY_OBJECT_ID;

	static
	{
		Map<Integer, AbyssRiftRune> rifts = new HashMap<>();
		for (AbyssRiftRune rift : values())
		{
			AbyssRiftRune previous = rifts.put(rift.objectId, rift);
			if (previous != null)
			{
				throw new IllegalStateException("Duplicate Abyss rift object mapping");
			}
		}
		BY_OBJECT_ID = Collections.unmodifiableMap(rifts);
	}

	private final int objectId;
	private final int runeItemId;
	private final String displayName;

	AbyssRiftRune(int objectId, int runeItemId, String displayName)
	{
		this.objectId = objectId;
		this.runeItemId = runeItemId;
		this.displayName = displayName;
	}

	int getObjectId()
	{
		return objectId;
	}

	int getRuneItemId()
	{
		return runeItemId;
	}

	String getDisplayName()
	{
		return displayName;
	}

	static AbyssRiftRune fromObjectId(int objectId)
	{
		return BY_OBJECT_ID.get(objectId);
	}
}

package com.abysshighlighter;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.util.HashMap;
import java.util.Map;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.DecorativeObject;
import net.runelite.api.Perspective;
import net.runelite.api.Player;
import net.runelite.api.Point;
import net.runelite.api.WorldView;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayUtil;

class AbyssRiftRuneHighlighterOverlay extends Overlay
{
	static final int ABYSS_REGION_ID = 12107;
	private static final int LABEL_GAP = 3;

	private final Client client;
	private final ItemManager itemManager;
	private final AbyssRiftRuneHighlighterPlugin plugin;
	private final AbyssRiftRuneHighlighterConfig config;
	private final Map<Integer, BufferedImage> runeImages = new HashMap<>();
	private Font cachedBaseFont;
	private Font cachedLabelFont;
	private int cachedFontSize = -1;

	@Inject
	AbyssRiftRuneHighlighterOverlay(
		Client client,
		ItemManager itemManager,
		AbyssRiftRuneHighlighterPlugin plugin,
		AbyssRiftRuneHighlighterConfig config)
	{
		this.client = client;
		this.itemManager = itemManager;
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		Player localPlayer = client.getLocalPlayer();
		if (localPlayer == null || localPlayer.getWorldLocation().getRegionID() != ABYSS_REGION_ID)
		{
			return null;
		}

		boolean showNames = config.showRuneNames();
		int iconSize = config.iconSize();
		int heightOffset = config.heightOffset();
		Color nameColor = showNames ? config.nameColor() : null;
		Font originalFont = graphics.getFont();
		if (showNames)
		{
			graphics.setFont(getLabelFont(originalFont, config.fontSize()));
		}

		try
		{
			for (DecorativeObject object : plugin.getTrackedAbyssRifts())
			{
				if (isInActiveWorldView(object))
				{
					renderRune(graphics, object, iconSize, heightOffset, showNames, nameColor);
				}
			}
		}
		finally
		{
			if (showNames)
			{
				graphics.setFont(originalFont);
			}
		}
		return null;
	}

	private void renderRune(
		Graphics2D graphics,
		DecorativeObject object,
		int iconSize,
		int heightOffset,
		boolean showNames,
		Color nameColor)
	{
		AbyssRiftRune rift = AbyssRiftRune.fromObjectId(object.getId());
		if (rift == null)
		{
			return;
		}

		BufferedImage image = runeImages.computeIfAbsent(
			rift.getRuneItemId(),
			itemManager::getImage
		);
		if (image == null)
		{
			return;
		}

		Point originalLocation = Perspective.getCanvasImageLocation(
			client,
			object.getLocalLocation(),
			image,
			heightOffset
		);
		if (originalLocation == null)
		{
			return;
		}

		int centerX = originalLocation.getX() + image.getWidth() / 2;
		int centerY = originalLocation.getY() + image.getHeight() / 2;
		int iconX = centerX - iconSize / 2;
		int iconY = centerY - iconSize / 2;
		graphics.drawImage(image, iconX, iconY, iconSize, iconSize, null);

		if (showNames)
		{
			renderName(graphics, rift.getDisplayName(), centerX, iconY + iconSize, nameColor);
		}
	}

	private void renderName(Graphics2D graphics, String name, int centerX, int iconBottom, Color nameColor)
	{
		int textX = centerX - graphics.getFontMetrics().stringWidth(name) / 2;
		int textY = iconBottom + LABEL_GAP + graphics.getFontMetrics().getAscent();
		OverlayUtil.renderTextLocation(
			graphics,
			new Point(textX, textY),
			name,
			nameColor
		);
	}

	private Font getLabelFont(Font baseFont, int fontSize)
	{
		if (cachedLabelFont == null || cachedFontSize != fontSize || !baseFont.equals(cachedBaseFont))
		{
			cachedBaseFont = baseFont;
			cachedFontSize = fontSize;
			cachedLabelFont = baseFont.deriveFont(Font.BOLD, (float) fontSize);
		}
		return cachedLabelFont;
	}

	void clearCaches()
	{
		runeImages.clear();
		cachedBaseFont = null;
		cachedLabelFont = null;
		cachedFontSize = -1;
	}

	private boolean isInActiveWorldView(DecorativeObject object)
	{
		WorldView activeWorldView = client.getTopLevelWorldView();
		Player localPlayer = client.getLocalPlayer();
		if (localPlayer != null && localPlayer.getWorldView() != null)
		{
			activeWorldView = localPlayer.getWorldView();
		}

		return activeWorldView != null
			&& object.getWorldView() != null
			&& object.getWorldView().getId() == activeWorldView.getId()
			&& object.getPlane() == activeWorldView.getPlane();
	}
}

package com.abysshighlighter;

import java.awt.Color;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Range;

@ConfigGroup(AbyssRiftRuneHighlighterConfig.CONFIG_GROUP)
public interface AbyssRiftRuneHighlighterConfig extends Config
{
	String CONFIG_GROUP = "abyss-rift-rune-highlighter";

	@ConfigItem(
		keyName = "showRuneNames",
		name = "Show rune names",
		description = "Shows each rune name beneath its icon",
		position = 0
	)
	default boolean showRuneNames()
	{
		return true;
	}

	@Range(min = 24, max = 72)
	@ConfigItem(
		keyName = "iconSize",
		name = "Icon size",
		description = "Size of rune icons above the rifts",
		position = 1
	)
	default int iconSize()
	{
		return 40;
	}

	@Range(min = 10, max = 24)
	@ConfigItem(
		keyName = "fontSize",
		name = "Font size",
		description = "Size of rune names beneath the icons",
		position = 2
	)
	default int fontSize()
	{
		return 14;
	}

	@Range(min = 80, max = 300)
	@ConfigItem(
		keyName = "heightOffset",
		name = "Height offset",
		description = "Vertical position of rune icons above the rifts",
		position = 3
	)
	default int heightOffset()
	{
		return 210;
	}

	@ConfigItem(
		keyName = "nameColor",
		name = "Name colour",
		description = "Colour used for rune names",
		position = 4
	)
	default Color nameColor()
	{
		return Color.WHITE;
	}
}

package com.abysshighlighter;

import com.google.inject.Provides;
import java.util.Collections;
import java.util.HashSet;
import java.util.Set;
import javax.inject.Inject;
import net.runelite.api.DecorativeObject;
import net.runelite.api.GameState;
import net.runelite.api.events.DecorativeObjectDespawned;
import net.runelite.api.events.DecorativeObjectSpawned;
import net.runelite.api.events.GameStateChanged;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

@PluginDescriptor(
	name = "Abyss Rift Rune Highlighter",
	description = "Shows the matching rune icon and name above every rift in the Abyss",
	tags = {"abyss", "rift", "rune", "runecraft", "runecrafting", "highlight", "overlay"}
)
public class AbyssRiftRuneHighlighterPlugin extends Plugin
{
	private final Set<DecorativeObject> trackedAbyssRifts = new HashSet<>();
	private final Set<DecorativeObject> trackedAbyssRiftsView = Collections.unmodifiableSet(trackedAbyssRifts);

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private AbyssRiftRuneHighlighterOverlay overlay;

	@Provides
	AbyssRiftRuneHighlighterConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(AbyssRiftRuneHighlighterConfig.class);
	}

	@Override
	protected void startUp()
	{
		overlayManager.add(overlay);
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(overlay);
		overlay.clearCaches();
		trackedAbyssRifts.clear();
	}

	@Subscribe
	public void onDecorativeObjectSpawned(DecorativeObjectSpawned event)
	{
		DecorativeObject object = event.getDecorativeObject();
		if (AbyssRiftRune.fromObjectId(object.getId()) != null)
		{
			trackedAbyssRifts.add(object);
		}
	}

	@Subscribe
	public void onDecorativeObjectDespawned(DecorativeObjectDespawned event)
	{
		trackedAbyssRifts.remove(event.getDecorativeObject());
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		GameState state = event.getGameState();
		if (state == GameState.LOADING || state == GameState.HOPPING || state == GameState.LOGIN_SCREEN)
		{
			trackedAbyssRifts.clear();
		}
	}

	Set<DecorativeObject> getTrackedAbyssRifts()
	{
		return trackedAbyssRiftsView;
	}
}
